# ---------------------------------------------------------------------------
# PNG helpers (pure standard library).
# ---------------------------------------------------------------------------
def png_dimensions(data: bytes) -> tuple[int, int]:
    """Return (width, height) from a PNG's IHDR chunk.

    Raises ValueError when the bytes are not a PNG or the header is short.
    """
    if len(data) < 24 or data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("not a PNG file (bad signature)")
    # IHDR chunk: 4-byte length, 4-byte type "IHDR", then width and height
    # as big-endian uint32.
    length, chunk_type = struct.unpack(">I4s", data[8:16])
    if chunk_type != b"IHDR" or length != 13:
        raise ValueError("not a PNG file (bad IHDR chunk)")
    width, height = struct.unpack(">II", data[16:24])
    return width, height


def check_gate(data: bytes) -> tuple[int, int]:
    """Check the decoded image against the competition gate.

    Returns the (width, height). Raises ValueError on any failure.
    """
    if len(data) > MAX_BYTES:
        raise ValueError(
            f"image is {len(data)} bytes, over the {MAX_BYTES} byte cap"
        )
    width, height = png_dimensions(data)
    if width > MAX_DIMENSION or height > MAX_DIMENSION:
        raise ValueError(
            f"image is {width}x{height}, over the "
            f"{MAX_DIMENSION}x{MAX_DIMENSION} cap"
        )
    return width, height


# ---------------------------------------------------------------------------
# Main.
# ---------------------------------------------------------------------------
def main() -> int:
    output_path = os.environ.get("ENTRY_OUTPUT", DEFAULT_OUTPUT)

    # Decode the embedded poster.
    try:
        image = base64.b64decode(POSTER_B64, validate=True)
    except Exception as exc:  # pragma: no cover - corrupt payload guard
        print(f"error: embedded poster is not valid base64: {exc}",
              file=sys.stderr)
        return 1

    # Gate-check before writing anything.
    try:
        width, height = check_gate(image)
    except ValueError as exc:
        print(f"error: poster fails the gate: {exc}", file=sys.stderr)
        return 1

    # Write it out.
    out_dir = os.path.dirname(output_path)
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    with open(output_path, "wb") as handle:
        handle.write(image)

    # Re-read the written file and verify it is exactly what we decoded.
    with open(output_path, "rb") as handle:
        written = handle.read()
    if written != image:
        print("error: written file differs from the decoded poster",
              file=sys.stderr)
        return 1
    check_gate(written)

    print(f"wrote {output_path}: PNG {width}x{height}, "
          f"{len(written)} bytes — THALORIS, Where Two Moons Rise")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
